def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    chain_dict = sorted(chain_dict.items(), key=lambda x: (-len(x[1]), x[0]))

    current = chain_dict[0][0]
    result = []

    while current in chain_dict:
        result.append(current)
        current = chain_dict[current][0]

    return ','.join(result)
